// ROUND-C2 (2.4): the long references `get_reference` serves, generated
// from the docs (never hand copied). `npm run build` runs it first, and a
// test fails when the generated file and the docs drift.
import { readFileSync, writeFileSync } from 'node:fs';

export const TOPICS = {
  'code-layer': 'docs/CODE-LAYER.md',
  blocks: 'docs/GRAPHICS-BLOCKS.md',
  freecode: 'docs/FREECODE-AUTHORING.md',
  'plan-format': 'docs/video-plan.md',
  camera: 'docs/camera.md',
  'capability-sheet': 'docs/CAPABILITY-SHEET.md',
};
export function referencesSource() {
  const body = Object.entries(TOPICS)
    .map(
      ([topic, file]) =>
        `  ${JSON.stringify(topic)}: ${JSON.stringify(readFileSync(file, 'utf8'))},`,
    )
    .join('\n');
  return `// GENERATED by scripts/mcp-references.mjs from the docs; do not edit.\n// ROUND-C2 (2.4): get_reference serves these.\nexport const REFERENCES: Readonly<Record<string, string>> = {\n${body}\n};\n`;
}
if (process.argv[1]?.endsWith('mcp-references.mjs'))
  writeFileSync('src/director-rules/references.gen.ts', referencesSource());
